const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const requestedSlot = payload.requestedSlot || payload.slot || payload.datetime;
const clientTz = payload.timezone || 'Asia/Kolkata';
const service = payload.service || 'Executive Architecture Consultation';
const existingBookings = Array.isArray(payload.existingBookings) ? payload.existingBookings : [];

if (!requestedSlot) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'failed',
      scheduling: {
        available: false,
        error: 'Missing requestedSlot timestamp in payload',
        conflictDetected: false
      }
    }
  }];
}

const reqDate = new Date(requestedSlot);
const isValidDate = !isNaN(reqDate.getTime());

if (!isValidDate) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'failed',
      scheduling: {
        available: false,
        error: 'Invalid date format for requestedSlot',
        conflictDetected: false
      }
    }
  }];
}

const reqTime = reqDate.getTime();
const BUFFER_MS = 45 * 60 * 1000;
let conflict = false;
let conflictingWith = null;

for (const b of existingBookings) {
  const bTime = new Date(b.slot || b.datetime || b.startTime).getTime();
  if (!isNaN(bTime) && Math.abs(reqTime - bTime) < BUFFER_MS) {
    conflict = true;
    conflictingWith = b;
    break;
  }
}

const dayOfWeek = reqDate.getUTCDay();
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
const hours = reqDate.getUTCHours();
const isOutOfHours = hours < 3 || hours > 14;

const isAvailable = !conflict && !isWeekend && !isOutOfHours;

const alternativeSlots = [];
if (!isAvailable) {
  for (let i = 1; alternativeSlots.length < 3 && i <= 7; i++) {
    const nextDay = new Date(reqTime + i * 24 * 60 * 60 * 1000);
    const nextDow = nextDay.getUTCDay();
    if (nextDow !== 0 && nextDow !== 6) {
      nextDay.setUTCHours(9, 0, 0, 0);
      alternativeSlots.push(nextDay.toISOString());
    }
  }
}

const schedulingResult = {
  available: isAvailable,
  conflictDetected: conflict,
  requestedSlot: reqDate.toISOString(),
  timezone: clientTz,
  service,
  confirmedSlot: isAvailable ? reqDate.toISOString() : null,
  alternativeSlots,
  bookingReference: isAvailable ? ('LIT-SCHED-' + Math.random().toString(36).substring(2, 9).toUpperCase()) : null,
  checkedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    scheduling: schedulingResult
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { scheduling: item.json.scheduling }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
